import java.util.*;
import java.lang.reflect.Field;
/** Reads physical container representation only; never invokes Fastjson accessors. */
public final class JsonTreeObservationHooks {
 static final Map<ClassLoader,Map<String,String>> LOADED=new IdentityHashMap<>();
 static Map config(){return (Map)PlannedServiceAgent.plan.get("json_tree_observation");}
 static boolean candidate(Object o){return System.getSecurityManager()==null&&o!=null&&config()!=null&&((Map)config().get("class_sha256")).containsKey(o.getClass().getName().replace('.','/'));}
 static void loaded(ClassLoader loader,String owner,byte[] bytes)throws Exception{if(config()==null||!((Map)config().get("class_sha256")).containsKey(owner))return;String digest=PlannedServiceAgent.Recorder.hash(bytes);if(!digest.equals(((Map)config().get("class_sha256")).get(owner)))throw new IllegalStateException("JSON tree loaded implementation differs");LOADED.computeIfAbsent(loader,k->new TreeMap<>()).put(owner,digest);Map r=PlannedServiceAgent.Recorder.row();r.put("class",owner);r.put("class_sha256",digest);r.put("loader",PlannedServiceAgent.Recorder.id(loader));PlannedServiceAgent.Recorder.emit("json-tree-class",r);}
 static Map check(Object o)throws Exception{String name=o.getClass().getName().replace('.','/');Map known=LOADED.get(o.getClass().getClassLoader());if(!candidate(o)||known==null||!Objects.equals(known.get(name),((Map)config().get("class_sha256")).get(name)))throw new IllegalStateException("JSON tree class not witnessed");Map runtime=new LinkedHashMap();runtime.put("java_runtime_version",System.getProperty("java.runtime.version"));runtime.put("class_sha256",JdkContractProbe.selected((String[])((Map)((Map)((List)config().get("profiles")).get(0)).get("class_sha256")).keySet().toArray(new String[0])));if(!((List)config().get("profiles")).contains(runtime))throw new IllegalStateException("JSON tree JDK representation differs");return runtime;}
 static final IdentityHashMap<Class<?>,Map<String,Field>> FIELDS=new IdentityHashMap<>();
 static synchronized Field field(Class<?> c,String name)throws Exception{Map<String,Field> fields=FIELDS.get(c);if(fields==null){fields=new HashMap<>();FIELDS.put(c,fields);}Field f=fields.get(name);if(f==null){f=c.getDeclaredField(name);f.setAccessible(true);fields.put(name,f);}return f;}
 static Object get(Class<?> c,Object o,String name)throws Exception{return field(c,name).get(o);}
 static final class Snapshot {
  final Object owner;final Map runtime;final int size,mod;final List<Object> values;final List<Map.Entry> pairs;final List<Object> observed;int epoch=-1;
  Snapshot(Object o)throws Exception{owner=o;runtime=check(o);boolean array=o.getClass().getName().equals("com.alibaba.fastjson2.JSONArray");size=(Integer)get(array?ArrayList.class:HashMap.class,o,"size");mod=(Integer)get(array?java.util.AbstractList.class:HashMap.class,o,"modCount");values=array?elements(o):null;pairs=array?null:entries(o);observed=new ArrayList<>();if(array){for(Object v:values)observed.add(PlannedServiceAgent.Recorder.value(v));}else{for(Map.Entry p:pairs){Map r=new LinkedHashMap();r.put("key",p.getKey());r.put("observed",PlannedServiceAgent.Recorder.value(p.getValue()));observed.add(r);}observed.sort((a,b)->((String)((Map)a).get("key")).compareTo((String)((Map)b).get("key")));}verify();}
  void verify()throws Exception{boolean array=values!=null;if(size!=(Integer)get(array?ArrayList.class:HashMap.class,owner,"size")||mod!=(Integer)get(array?java.util.AbstractList.class:HashMap.class,owner,"modCount"))throw new IllegalStateException("JSON snapshot stage changed");if(array){Object[] now=(Object[])get(ArrayList.class,owner,"elementData");if(now.length<size)throw new IllegalStateException("JSON snapshot storage changed");for(int i=0;i<size;i++)if(now[i]!=values.get(i))throw new IllegalStateException("JSON snapshot member changed");}else{List<Map.Entry> now=entries(owner);if(now.size()!=pairs.size())throw new IllegalStateException("JSON snapshot map changed");for(int i=0;i<now.size();i++)if(now.get(i).getKey()!=pairs.get(i).getKey()||now.get(i).getValue()!=pairs.get(i).getValue())throw new IllegalStateException("JSON snapshot entry changed");}}
 }
 static Snapshot snapshot(Object o)throws Exception{return new Snapshot(o);}
 static List<Object> elements(Object o)throws Exception{check(o);if(!o.getClass().getName().equals("com.alibaba.fastjson2.JSONArray")||o.getClass().getSuperclass()!=ArrayList.class)throw new IllegalStateException("JSON array hierarchy differs");int size=(Integer)get(ArrayList.class,o,"size"),mod=(Integer)get(java.util.AbstractList.class,o,"modCount");if(size<0||size>10000)throw new IllegalStateException("JSON array bound");Object[] values=(Object[])get(ArrayList.class,o,"elementData");if(values.length<size)throw new IllegalStateException("JSON array storage differs");List<Object> result=new ArrayList<>();for(int i=0;i<size;i++)result.add(values[i]);if(size!=(Integer)get(ArrayList.class,o,"size")||mod!=(Integer)get(java.util.AbstractList.class,o,"modCount"))throw new IllegalStateException("JSON array changed during snapshot");return result;}
 static List<Map.Entry> entries(Object o)throws Exception{check(o);if(!o.getClass().getName().equals("com.alibaba.fastjson2.JSONObject")||o.getClass().getSuperclass()!=LinkedHashMap.class)throw new IllegalStateException("JSON object hierarchy differs");int size=(Integer)get(HashMap.class,o,"size"),mod=(Integer)get(HashMap.class,o,"modCount");if(size<0||size>10000)throw new IllegalStateException("JSON object bound");Object[] table=(Object[])get(HashMap.class,o,"table");Class<?> node=Class.forName("java.util.HashMap$Node",false,null),entry=Class.forName("java.util.LinkedHashMap$Entry",false,null);List<Map.Entry> result=new ArrayList<>();IdentityHashMap<Object,Boolean> seen=new IdentityHashMap<>();if(table!=null)for(Object first:table)for(Object n=first;n!=null;n=get(node,n,"next")){if(n.getClass()!=entry||seen.put(n,true)!=null||result.size()>=size)throw new IllegalStateException("JSON object node shape differs");Object key=get(node,n,"key");if(key==null||key.getClass()!=String.class)throw new IllegalStateException("JSON object key differs");result.add(new AbstractMap.SimpleImmutableEntry(key,get(node,n,"value")));}if(result.size()!=size||size!=(Integer)get(HashMap.class,o,"size")||mod!=(Integer)get(HashMap.class,o,"modCount"))throw new IllegalStateException("JSON object changed during snapshot");return result;}
 static List<Object> contents(Object o)throws Exception{List<Object> result=new ArrayList<>();if(o.getClass().getName().equals("com.alibaba.fastjson2.JSONArray")){for(Object v:elements(o))result.add(PlannedServiceAgent.Recorder.value(v));}else{for(Map.Entry p:entries(o)){Map x=new LinkedHashMap();x.put("key",p.getKey());x.put("observed",PlannedServiceAgent.Recorder.value(p.getValue()));result.add(x);}result.sort((a,b)->((String)((Map)a).get("key")).compareTo((String)((Map)b).get("key")));}return result;}
 static Map proof(Object o,String path,Snapshot snapshot)throws Exception{Map r=ResponseBindingHooks.row();r.put("owner",PlannedServiceAgent.Recorder.id(o));r.put("class",o.getClass().getName().replace('.','/'));r.put("loader",PlannedServiceAgent.Recorder.id(o.getClass().getClassLoader()));r.put("class_sha256",((Map)config().get("class_sha256")).get(r.get("class")));r.put("runtime",snapshot.runtime);r.put("path",path);r.put("source_capture",ResponseBindingHooks.sourceCapture);snapshot.epoch=CollectionServiceHooks.epoch(o,snapshot.observed);r.put("epoch",snapshot.epoch);r.put("contents",snapshot.observed);if(!CollectionServiceHooks.CALLS.get().isEmpty())r.put("call_id",CollectionServiceHooks.CALLS.get().peek().get("call_id"));PlannedServiceAgent.Recorder.emit("json-tree-container",r);return r;}
}
